package zw.chibaro;
import java.util.*;
import java.time.*;
import java.security.Principal;
import jakarta.validation.Valid;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1")
public class ApiController {
 final JdbcTemplate db;final Operations ops;
 public ApiController(JdbcTemplate db,Operations ops){this.db=db;this.ops=ops;}
 @GetMapping("/auth/csrf") Map<String,String> csrf(CsrfToken token){return Map.of("token",token.getToken(),"headerName",token.getHeaderName());}
 @GetMapping("/auth/me") Map<String,String> me(Principal principal){return Map.of("email",principal.getName());}
 @GetMapping("/services") Object services(){return db.queryForList("select id,name,description from business_services where active order by id");}
 @GetMapping("/service-areas") Object areas(){return db.queryForList("select id,name from service_areas where verified order by name");}
 @GetMapping("/fleet") Object fleet(){return db.queryForList("select id,name,capacity_kg,approved_photo_url from vehicles where active");}
 @PostMapping("/quotes") @ResponseStatus(HttpStatus.CREATED) Object quote(@Valid @RequestBody Contracts.Request r){return ops.submit(r,false);}
 @PostMapping("/bookings") @ResponseStatus(HttpStatus.CREATED) Object booking(@Valid @RequestBody Contracts.Request r){return ops.submit(r,true);}
 @PostMapping("/contact") @ResponseStatus(HttpStatus.CREATED) Object contact(@Valid @RequestBody Contracts.Contact r){ops.contact(r);return Map.of("message","Your enquiry has been received. Contact us on WhatsApp for human assistance.");}
 @GetMapping("/admin/{resource:quotes|bookings|leads|customers|fleet|services|service-areas|notifications|audit}") Object list(@PathVariable String resource,@RequestParam(defaultValue="0") int page){if(page<0||page>100000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid page.");String sql=switch(resource){case "quotes"->"select q.*,c.name,c.phone,c.email from quotation_requests q join customers c on c.id=q.customer_id order by q.created_at desc";case "bookings"->"select q.*,c.name,c.phone,c.email from bookings q join customers c on c.id=q.customer_id order by q.created_at desc";case "leads"->"select q.*,c.name,c.phone,c.email from leads q join customers c on c.id=q.customer_id order by q.created_at desc";case "customers"->"select * from customers order by created_at desc";case "fleet"->"select * from vehicles order by name";case "services"->"select * from business_services order by name";case "service-areas"->"select * from service_areas order by name";case "notifications"->"select * from notification_outbox order by created_at desc";default->"select * from audit_logs order by created_at desc";};return db.queryForList(sql+" limit 50 offset ?",page*50);}
 @GetMapping("/admin/quotes/{id}") Object quoteDetail(@PathVariable UUID id){var rows=db.queryForList("select q.*,c.name,c.phone,c.email from quotation_requests q join customers c on c.id=q.customer_id where q.id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return rows.getFirst();}
 @PatchMapping("/admin/quotes/{id}") Object updateQuote(@PathVariable UUID id,@Valid @RequestBody Contracts.QuoteUpdate r,Principal p){ops.quote(id,r,p.getName());return Map.of("ok",true);}
 @PostMapping("/admin/quotes/{id}/convert") Object convert(@PathVariable UUID id,Principal p){return ops.convert(id,p.getName());}
 @PatchMapping("/admin/bookings/{id}") Object updateBooking(@PathVariable UUID id,@Valid @RequestBody Contracts.BookingUpdate r,Principal p){ops.booking(id,r,p.getName());return Map.of("ok",true);}
 @PatchMapping("/admin/leads/{id}") Object updateLead(@PathVariable UUID id,@Valid @RequestBody Contracts.LeadUpdate r,Principal p){ops.lead(id,r,p.getName());return Map.of("ok",true);}
 @GetMapping({"/admin/dashboard","/admin/analytics/overview"}) Object analytics(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to){LocalDate start=from==null?LocalDate.now().minusDays(29):from;LocalDate end=to==null?LocalDate.now():to;if(end.isBefore(start)||start.plusYears(2).isBefore(end))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a date range of up to two years.");Map<String,Object> result=new LinkedHashMap<>();result.put("from",start);result.put("to",end);result.put("quotations",count("quotation_requests","",start,end));result.put("newEnquiries",count("leads"," and status='NEW'",start,end));result.put("pendingQuotations",count("quotation_requests"," and status in ('NEW','UNDER_REVIEW')",start,end));result.put("acceptedQuotations",count("quotation_requests"," and status='ACCEPTED'",start,end));result.put("confirmedBookings",count("bookings"," and status in ('CONFIRMED','SCHEDULED','IN_PROGRESS')",start,end));result.put("completedDeliveries",count("bookings"," and status='COMPLETED'",start,end));result.put("scheduledAdvertisements",count("marketing_posts"," and status='SCHEDULED'",start,end));result.put("publishedAdvertisements",count("marketing_posts"," and status='PUBLISHED'",start,end));result.put("failedAdvertisements",count("marketing_posts"," and status='FAILED'",start,end));result.put("sources",db.queryForList("select source,count(*) as count from leads where created_at>=?::date and created_at<(?::date+interval '1 day') group by source",start,end));result.put("trend",db.queryForList("select created_at::date as date,count(*) as count from leads where created_at>=?::date and created_at<(?::date+interval '1 day') group by 1 order by 1",start,end));result.put("socialMetricsAvailable",false);return result;}
 long count(String table,String where,LocalDate start,LocalDate end){return db.queryForObject("select count(*) from "+table+" where created_at>=?::date and created_at<(?::date+interval '1 day')"+where,Long.class,start,end);}
 @PostMapping("/assistant/messages") Object assistant(@Valid @RequestBody Contracts.Chat r){String message=r.message().toLowerCase(Locale.ROOT);String answer;if(message.matches(".*(price|cost|rate|available|tomorrow|guarantee).*"))answer="Prices, availability and dates need review by our team. Request a quotation or contact WhatsApp +263 77 500 8064; submitting a request does not confirm transport.";else if(message.matches(".*(area|where|coverage|africa|botswana|operate).*"))answer="Our verified service areas are: "+String.join(", ",db.queryForList("select name from service_areas where verified order by name",String.class))+". Please ask our team to review any other destination.";else if(message.matches(".*(service|furniture|house|move|cargo).*"))answer="Our services include "+String.join(", ",db.queryForList("select name from business_services where active",String.class))+". Each load and route is reviewed before confirmation.";else answer="TransChibaro Logistics is based in Beitbridge. Submit a quotation request with pickup, destination and load details, or speak to our team on WhatsApp +263 77 500 8064. Calls: +263 783 051 430. Email: kamhungachibs@gmail.com.";return Map.of("answer",answer,"mode","verified-information","humanUrl","https://wa.me/263775008064");}
}
